const ctx = $('Entrada').first().json;
const r = $input.first().json;
let subestado = r.subestado || 'items';
const t = (ctx.mensaje && ctx.mensaje.texto) || '';
if (subestado === 'resumen' && (t === 'PAGO_EF' || t === 'PAGO_TR')) subestado = 'pago';
return [{ json: { ...ctx, autor: 'bot', guardar_contenido: false, carrito: r.carrito || { items: [] }, subestado } }];

const ctx = $('Contexto de pedido').first().json;
const cat = $input.all().map(i => i.json.nombre).filter(Boolean);
return [{ json: { ...ctx, ia: { modo: 'items', texto: ctx.mensaje.texto, catalogo: cat } } }];

const ia = $input.first().json;
const cat = $('Cargar catálogo').all().map(i => i.json);
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
const encontrados = [], faltantes = [];
let cantidad_invalida = false;
for (const it of (ia.items || [])) {
  if (!(it.cantidad > 0)) { cantidad_invalida = true; continue; }
  const p = cat.find(c => norm(c.nombre) === norm(it.producto)) || cat.find(c => norm(it.producto).length > 2 && norm(c.nombre).includes(norm(it.producto)));
  if (!p) faltantes.push({ nombre: it.producto, motivo: 'inexistente', categoria: null });
  else if (!p.disponible) faltantes.push({ nombre: p.nombre, motivo: 'agotado', categoria: p.categoria });
  else encontrados.push({ producto_id: p.id, nombre: p.nombre, precio: p.precio, cantidad: it.cantidad, especificaciones: it.especificaciones || '' });
}
const ctx = $('Contexto de pedido').first().json;
return [{ json: { ...ctx, encontrados, faltantes, cantidad_invalida } }];

const ctx = $('Contexto de pedido').first().json;
const falt = $('Resolver ítems contra catálogo').first().json.faltantes.map(f => f.nombre).join(', ') || 'tu mensaje';
const alt = $input.all().filter(i => i.json.nombre);
const textoAlt = alt.length ? 'Alternativas disponibles: ' + alt.map(i => i.json.nombre + ' ($' + Number(i.json.precio).toLocaleString('es-CO') + ')').join(', ') + '. ' : '';
return [{ json: { ...ctx, autor: 'bot', guardar_contenido: false, wa: { tipo: 'texto', texto: 'No pude agregar: ' + falt + ' (inexistente, agotado o cantidad inválida). ' + textoAlt + 'Escribe menú o pide hablar con una persona.' } } }];

const ctx = $('Contexto de pedido').first().json;
const enc = $('Resolver ítems contra catálogo').first().json.encontrados;
return [{ json: { ...ctx, autor: 'bot', guardar_contenido: false, wa: { tipo: 'botones', texto: 'Agregué: ' + enc.map(i => i.cantidad + ' x ' + i.nombre + (i.especificaciones ? ' (' + i.especificaciones + ')' : '')).join(', ') + '. ¿Algo más?', botones: [{ id: 'PED_MAS', titulo: 'Agregar más' }, { id: 'PED_CONTINUAR', titulo: 'Continuar' }] } } }];

const ctx = $input.first().json;
const t = ctx.mensaje.texto;
return [{ json: { ...ctx, entrega: t === 'ENT_DOM' ? 'domicilio' : t === 'ENT_REC' ? 'recogida' : null } }];

const ctx = $input.first().json;
const c = ctx.carrito || {};
const t = (ctx.mensaje.texto || '').trim();
let nombre = c.nombre || null, direccion = c.direccion || null;
if (!nombre) nombre = t.slice(0, 80);
else if (c.entrega === 'domicilio' && !direccion) direccion = t.slice(0, 160);
const falta = (c.entrega === 'domicilio' && !direccion) ? 'direccion' : null;
return [{ json: { ...ctx, nombre, direccion, falta } }];

const ctx = $input.first().json;
const t = ctx.mensaje.texto;
return [{ json: { ...ctx, pago: t === 'PAGO_EF' ? 'efectivo' : t === 'PAGO_TR' ? 'transferencia' : null } }];

const ctx = $('Contexto de pedido').first().json;
const r = $input.first().json;
let pago = null;
try { pago = $('Validar método de pago').first().json.pago; } catch (e) {}
pago = pago || (ctx.carrito && ctx.carrito.pago) || '';
let resumen = '';
try { resumen = $('Calcular resumen (total en BD)').first().json.resumen_texto || ''; } catch (e) {}
const total = '$' + Number(r.total).toLocaleString('es-CO');
const cab = 'Pedido #' + r.numero + ' registrado. Total: ' + total;
let texto;
if (pago === 'transferencia') {
  texto = cab + '\n\nPara pagar por transferencia usa estos datos:\n' + (ctx.comercio.datos_transferencia || '');
} else if (ctx.carrito && ctx.carrito.entrega === 'domicilio') {
  texto = '¡Perfecto! Pagas en efectivo cuando recibas tu pedido.\n\n' + cab;
} else {
  texto = '¡Perfecto! Te esperamos para que recojas tu pedido.\nDirección: ' + (ctx.comercio.direccion || '') + '\n\n' + cab;
}
if (resumen) texto += '\n\n' + resumen;
texto += '\n\nEscribe menú para volver.';
return [{ json: { ...ctx, autor: 'bot', guardar_contenido: false, wa: { tipo: 'texto', texto } } }];
